import{_ as p,a0 as t,w as o,s as d,I as l,x as s,a1 as e,A as i,ao as c}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"初識 Python： global 關鍵字 | LCTT x X-CMD","titleTemplate":false,"description":"初識 Python： global 關鍵字 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初識 Python： global 關鍵字 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初識 Python： global 關鍵字 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180207 Python Global Keyword (With Examples)","title":"初識 Python： global 關鍵字","tag":"201804","desc":""},"relativePath":"201804/20180207 Python Global Keyword (With Examples).md","filePath":"[post].md"}'),r={name:"201804/20180207 Python Global Keyword (With Examples).md"};function h(g,a,b,k,u,f){const n=t("Link");return o(),d("div",null,[a[16]||(a[16]=l("h1",{id:"初識-python-global-關鍵字",tabindex:"-1"},[s("初識 Python： global 關鍵字 "),l("a",{class:"header-anchor",href:"#初識-python-global-關鍵字","aria-label":"Permalink to “初識 Python： global 關鍵字”"},"​")],-1)),l("p",null,[a[1]||(a[1]=s("在讀這篇文章之前，確保你對 ",-1)),e(n,{href:"https://www.programiz.com/python-programming/global-local-nonlocal-variables"},{default:i(()=>[...a[0]||(a[0]=[s("Python 全局、本地和非本地變量",-1)])]),_:1}),a[2]||(a[2]=s(" 有一定的基礎。",-1))]),a[17]||(a[17]=c(`<h3 id="global-關鍵字簡介" tabindex="-1">global 關鍵字簡介 <a class="header-anchor" href="#global-關鍵字簡介" aria-label="Permalink to “global 關鍵字簡介”">​</a></h3><p>在 Python 中，<code>global</code> 關鍵字允許你修改當前範圍之外的變量。它用於創建全局變量並在本地上下文中更改變量。</p><h3 id="global-關鍵字的規則" tabindex="-1">global 關鍵字的規則 <a class="header-anchor" href="#global-關鍵字的規則" aria-label="Permalink to “global 關鍵字的規則”">​</a></h3><p>在 Python 中，有關 <code>global</code> 關鍵字基本規則如下：</p><ul><li>當我們在一個函數中創建一個變量時，默認情況下它是本地變量。</li><li>當我們在一個函數之外定義一個變量時，默認情況下它是全局變量。你不必使用 <code>global</code> 關鍵字。</li><li>我們使用 <code>global</code> 關鍵字在一個函數中來讀寫全局變量。</li><li>在一個函數外使用 <code>global</code> 關鍵字沒有效果。</li></ul><h3 id="使用-global-關鍵字-含示例" tabindex="-1">使用 global 關鍵字（含示例） <a class="header-anchor" href="#使用-global-關鍵字-含示例" aria-label="Permalink to “使用  global 關鍵字（含示例）”">​</a></h3><p>我們來舉個例子。</p><h4 id="示例-1-從函數內部訪問全局變量" tabindex="-1">示例 1：從函數內部訪問全局變量 <a class="header-anchor" href="#示例-1-從函數內部訪問全局變量" aria-label="Permalink to “示例 1：從函數內部訪問全局變量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c = 1 # 全局變量</span></span>
<span class="line"><span>def add():</span></span>
<span class="line"><span>	print(c)</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>add()</span></span></code></pre></div><p>運行程序，輸出為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>1</span></span></code></pre></div><p>但是我們可能有一些場景需要從函數內部修改全局變量。</p><h4 id="示例-2-在函數內部修改全局變量" tabindex="-1">示例 2：在函數內部修改全局變量 <a class="header-anchor" href="#示例-2-在函數內部修改全局變量" aria-label="Permalink to “示例 2：在函數內部修改全局變量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c = 1 # 全局變量</span></span>
<span class="line"><span>def add():</span></span>
<span class="line"><span>	c = c + 2 # 將 c 增加 2</span></span>
<span class="line"><span>	print(c)</span></span>
<span class="line"><span>add()</span></span></code></pre></div><p>運行程序，輸出顯示錯誤：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UnboundLocalError: local variable &#39;c&#39; referenced before assignment</span></span></code></pre></div><p>這是因為在函數中，我們只能訪問全局變量但是不能修改它。</p><p>解決的辦法是使用 <code>global</code> 關鍵字。</p><h4 id="示例-3-使用-global-在函數中改變全局變量" tabindex="-1">示例 3：使用 global 在函數中改變全局變量 <a class="header-anchor" href="#示例-3-使用-global-在函數中改變全局變量" aria-label="Permalink to “示例 3：使用 global 在函數中改變全局變量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>c = 0 # global variable</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>def add():</span></span>
<span class="line"><span>	global c</span></span>
<span class="line"><span>	c = c + 2 # 將 c 增加 2</span></span>
<span class="line"><span>	print(&quot;Inside add():&quot;, c)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>add()</span></span>
<span class="line"><span>print(&quot;In main:&quot;, c)</span></span></code></pre></div><p>運行程序，輸出為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Inside add(): 2</span></span>
<span class="line"><span>In main: 2</span></span></code></pre></div><p>在上面的程序中，我們在 <code>add()</code> 函數中定義了 <code>c</code> 將其作為全局關鍵字。</p><p>然後，我們給變量 <code>c</code> 增加 <code>2</code>，即 <code>c = c + 2</code>。之後，我們調用了 <code>add()</code> 函數。最後，打印全局變量 <code>c</code>。</p><p>正如我們所看到的，在函數外的全局變量也發生了變化，<code>c = 2</code>。</p><h3 id="python-模組中的全局變量" tabindex="-1">Python 模組中的全局變量 <a class="header-anchor" href="#python-模組中的全局變量" aria-label="Permalink to “Python 模組中的全局變量”">​</a></h3><p>在 Python 中，我們創建一個單獨的模組 <code>config.py</code> 來保存全局變量並在同一個程序中的 Python 模組之間共享信息。</p><p>以下是如何通過 Python 模組共享全局變量。</p><h4 id="示例-4-在python模組中共享全局變量" tabindex="-1">示例 4：在Python模組中共享全局變量 <a class="header-anchor" href="#示例-4-在python模組中共享全局變量" aria-label="Permalink to “示例 4：在Python模組中共享全局變量”">​</a></h4><p>創建 <code>config.py</code> 文件來存儲全局變量</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>a = 0</span></span>
<span class="line"><span>b = &quot;empty&quot;</span></span></code></pre></div><p>創建 <code>update.py</code> 文件來改變全局變量</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import config</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>config.a = 10</span></span>
<span class="line"><span>config.b = &quot;alphabet&quot;</span></span></code></pre></div><p>創建 <code>main.py</code> 文件來測試其值的變化</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import config</span></span>
<span class="line"><span>import update</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>print(config.a)</span></span>
<span class="line"><span>print(config.b)</span></span></code></pre></div><p>運行 <code>main.py</code>，輸出為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>10</span></span>
<span class="line"><span>alphabet</span></span></code></pre></div><p>在上面，我們創建了三個文件： <code>config.py</code>, <code>update.py</code> 和 <code>main.py</code>。</p><p>在 <code>config.py</code> 模組中保存了全局變量 <code>a</code> 和 <code>b</code>。在 <code>update.py</code> 文件中，我們導入了 <code>config.py</code> 模組並改變了 <code>a</code> 和 <code>b</code> 的值。同樣，在 <code>main.py</code> 文件，我們導入了 <code>config.py</code> 和 <code>update.py</code> 模組。最後，我們打印並測試全局變量的值，無論它們是否被改變。</p><h3 id="在嵌套函數中的全局變量" tabindex="-1">在嵌套函數中的全局變量 <a class="header-anchor" href="#在嵌套函數中的全局變量" aria-label="Permalink to “在嵌套函數中的全局變量”">​</a></h3><p>以下是如何在嵌套函數中使用全局變量。</p><h4 id="示例-5-在嵌套函數中使用全局變量" tabindex="-1">示例 5：在嵌套函數中使用全局變量 <a class="header-anchor" href="#示例-5-在嵌套函數中使用全局變量" aria-label="Permalink to “示例 5：在嵌套函數中使用全局變量”">​</a></h4><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>def foo():</span></span>
<span class="line"><span>	x = 20</span></span>
<span class="line"><span>	def bar():</span></span>
<span class="line"><span>		 global x</span></span>
<span class="line"><span>		 x = 25</span></span>
<span class="line"><span>	</span></span>
<span class="line"><span>	print(&quot;Before calling bar: &quot;, x)</span></span>
<span class="line"><span>	print(&quot;Calling bar now&quot;)</span></span>
<span class="line"><span>	bar()</span></span>
<span class="line"><span>	print(&quot;After calling bar: &quot;, x)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>foo()</span></span>
<span class="line"><span>print(&quot;x in main : &quot;, x)</span></span></code></pre></div><p>輸出為：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Before calling bar: 20</span></span>
<span class="line"><span>Calling bar now</span></span>
<span class="line"><span>After calling bar: 20</span></span>
<span class="line"><span>x in main : 25</span></span></code></pre></div><p>在上面的程序中，我們在一個嵌套函數 <code>bar()</code> 中聲明瞭全局變量。在 <code>foo()</code> 函數中， 變量 <code>x</code> 沒有全局關鍵字的作用。</p><p>調用 <code>bar()</code> 之前和之後， 變量 <code>x</code> 取本地變量的值，即 <code>x = 20</code>。在 <code>foo()</code> 函數之外，變量 <code>x</code> 會取在函數 <code>bar()</code> 中的值，即 <code>x = 25</code>。這是因為在 <code>bar()</code> 中，我們對 <code>x</code> 使用 <code>global</code> 關鍵字創建了一個全局變量（本地範圍）。</p><p>如果我們在 <code>bar()</code> 函數內進行了任何修改，那麼這些修改就會出現在本地範圍之外，即 <code>foo()</code>。</p><hr>`,49)),l("p",null,[a[4]||(a[4]=s("via: ",-1)),e(n,{href:"https://www.programiz.com/python-programming/global-keyword"},{default:i(()=>[...a[3]||(a[3]=[s("https://www.programiz.com/python-programming/global-keyword",-1)])]),_:1})]),l("p",null,[a[8]||(a[8]=s("作者：",-1)),e(n,{href:"https://www.programiz.com"},{default:i(()=>[...a[5]||(a[5]=[s("programiz",-1)])]),_:1}),a[9]||(a[9]=s(" 譯者：",-1)),e(n,{href:"https://github.com/MjSeven"},{default:i(()=>[...a[6]||(a[6]=[s("MjSeven",-1)])]),_:1}),a[10]||(a[10]=s(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...a[7]||(a[7]=[s("wxy",-1)])]),_:1})]),l("p",null,[a[13]||(a[13]=s("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...a[11]||(a[11]=[s("LCTT",-1)])]),_:1}),a[14]||(a[14]=s(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...a[12]||(a[12]=[s("Linux中國",-1)])]),_:1}),a[15]||(a[15]=s(" 榮譽推出",-1))])])}const C=p(r,[["render",h]]);export{x as __pageData,C as default};
